INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_r1_b001_003', 'topic_nsmq_phys_waves', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'Which colour of visible light has the longest wavelength?', 'multiple_choice', 'round_one', '["A. Violet","B. Green","C. Red","D. Blue"]', 'C', 'In the visible spectrum, red light has the longest wavelength (about 700 nm) and violet the shortest (about 400 nm). Frequency runs the opposite way because v = fλ for a fixed speed of light.', 'medium', '3', '1', '30', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_nsmq_phys_r1_b001_004', 'topic_nsmq_phys_modern_physics', 'subj_nsmq_physics', 'exam_nsmq', NULL, NULL, 'The photoelectric effect provides evidence that light can behave as', 'multiple_choice', 'round_one', '["A. Only a continuous wave","B. A longitudinal sound wave","C. A standing wave","D. A stream of particles (photons)"]', 'D', 'Einstein explained the photoelectric effect by treating light as quanta (photons) with energy E = hf. The existence of a threshold frequency cannot be explained by a purely continuous wave model.', 'medium', '3', '1', '30', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL);
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'nsmq-expansion-beta-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_nsmq_phys_r1_b001_001', 'q_nsmq_phys_r1_b001_002', 'q_nsmq_phys_r1_b001_003', 'q_nsmq_phys_r1_b001_004');
DELETE FROM _migration_393_guard;
INSERT INTO _migration_393_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions WHERE id IN ('q_nsmq_phys_r1_b001_001', 'q_nsmq_phys_r1_b001_002', 'q_nsmq_phys_r1_b001_003', 'q_nsmq_phys_r1_b001_004')) = 4 AND (SELECT COUNT(*) FROM question_content_releases r WHERE r.question_id IN ('q_nsmq_phys_r1_b001_001', 'q_nsmq_phys_r1_b001_002', 'q_nsmq_phys_r1_b001_003', 'q_nsmq_phys_r1_b001_004') AND r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 4 THEN 1 ELSE 0 END;
